const CHAPTERS = ['22', '23', '24'];

// 靶经：每章归经覆盖最高的一条，不做跨章合并 —— 合并会糊掉「每章一条轴」
const targetChannel = (no) => {
  const top = jingDist([no])[0];
  return { jing: top[0], n: drugsAll([no]).filter((d) => d.nature.guijing.includes(top[0])).length };
};

// 缺口：字段为空就报出来，绝不补
const missingNature = () =>
  drugsAll().filter((d) => d.nature.wei.length === 0 || d.nature.guijing.length === 0);
```
